<?php
declare(strict_types=1);
require dirname(__DIR__,2).'/app/bootstrap.php';
require __DIR__.'/migration-sequence.php';
use Kios\Infrastructure\{Database,StaffAccountService};
use Kios\MerchantOperations\{StaffSessionIdentity,Entitlements,Seating,StaffPos,Inventory,OperationalAnalytics,BillDrafts};
$db=Database::connect();$meta=json_decode(file_get_contents($argv[1]),true);$secrets=json_decode(file_get_contents($argv[2]),true);
$a=$meta['merchants']['a'];$b=$meta['merchants']['b'];$c=$meta['merchants']['c'];
$r=['passed'=>0,'failed'=>0,'cases'=>[]];$t=intdiv(time(),60)*60;
function yes(bool $v):void{if(!$v)throw new RuntimeException('Assertion failed');}
function denied(callable $f):void{try{$f();}catch(DomainException|InvalidArgumentException|PDOException){return;}throw new RuntimeException('Expected rejection');}
function test(string $n,callable $f):void{global$r;try{$f();$r['passed']++;$r['cases'][$n]='PASS';}catch(Throwable $x){$r['failed']++;$r['cases'][$n]=get_class($x).': '.$x->getMessage().' at '.basename($x->getFile()).':'.$x->getLine();}}
function kid():string{return bin2hex(random_bytes(16));}
function login(array $m,string $name,string $pw):StaffSessionIdentity{global$db;$q=$db->prepare('SELECT outlet_code FROM outlets WHERE outlet_id=?');$q->execute([$m['loginOutlet']]);$n=(new StaffAccountService($db,$q->fetchColumn(),getenv('KIOS_MERCHANT_AUTH_RATE_KEY')))->authenticate($name,$pw,'m06b-synthetic');yes($n!==null);$session=[];StaffAccountService::bind($session,$n);$session['_merchant_login_outlet']=(int)$m['loginOutlet'];return new StaffSessionIdentity($db,static fn()=>$session,getenv('KIOS_MERCHANT_AUTH_RATE_KEY'));}
$platform=login($meta['platform'],$secrets['platform_username'],$secrets['platform_password']);$oa=login($a,$a['username'],$secrets['owner_a_password']);$ob=login($b,$b['username'],$secrets['owner_b_password']);$oc=login($c,$c['username'],$secrets['owner_c_password']);
putenv('KIOS_ENTITLEMENTS_ENABLED=1');putenv('KIOS_SUBSCRIPTION_LIFECYCLE_ENABLED=1');
$e=new Entitlements($db,$platform,static fn()=>$GLOBALS['t']);
function versions(array $m):array{global$db;$q=$db->prepare('SELECT COALESCE(MAX(version),0) FROM merchant_subscription_events WHERE merchant_id=?');$q->execute([$m['merchant']]);$v=(string)$q->fetchColumn();$q=$db->prepare('SELECT version FROM merchant_plan_heads WHERE merchant_id=?');$q->execute([$m['merchant']]);return[$v,(string)$q->fetchColumn()];}
function fields(array $override=[]):array{global$t;return array_replace(['choice'=>'enterprise:3','effective'=>gmdate('Y-m-d\TH:i',$t),'expires'=>gmdate('Y-m-d\TH:i',$t+30*86400),'trial_end'=>gmdate('Y-m-d\TH:i',$t+7*86400),'grace_days'=>'2','renewable'=>'1','reason'=>'Synthetic lifecycle qualification'],$override);}
function act(array $m,string $action,array $over=[],?string $key=null):array{global$e;[$v,$h]=versions($m);return$e->lifecycle($key??kid(),$m['merchant'],$v,$h,$action,fields($over));}
function view(array $m,StaffSessionIdentity $auth):array{global$db;return(new Entitlements($db,$auth,static fn()=>$GLOBALS['t']))->overview($m['merchant'],$m['outlet']);}
function fingerprint():array{global$db;$r=[];foreach(['orders','order_items','payment_confirmations','print_jobs','merchant_inventory_items','merchant_inventory_movements','merchant_inventory_events','merchant_service_sessions','merchant_bill_drafts','merchant_bill_revisions']as$tbl)$r[$tbl]=hash('sha256',serialize($db->query('SELECT * FROM '.$tbl.' ORDER BY 1')->fetchAll(PDO::FETCH_ASSOC)));return$r;}
if(($argv[4]??'')==='worker'){try{echo json_encode($e->lifecycle($argv[5],$argv[6],$argv[7],$argv[8],'suspend',fields()));exit(0);}catch(Throwable$x){echo get_class($x).':'.$x->getMessage();exit(1);}}
$before=fingerprint();$base=$t;
test('Lifecycle disabled by default and native platform authorization remains mandatory',function()use($db,$oa,$a){putenv('KIOS_SUBSCRIPTION_LIFECYCLE_ENABLED=0');denied(fn()=>act($a,'adopt'));putenv('KIOS_SUBSCRIPTION_LIFECYCLE_ENABLED=1');[$v,$h]=versions($a);denied(fn()=>(new Entitlements($db,$oa))->lifecycle(kid(),$a['merchant'],$v,$h,'adopt',fields()));});
test('Adopt preserves A pinned M06A period and initializes immutable lifecycle',function()use($a,$oa){$prior=view($a,$oa)['assignment'];act($a,'adopt',['renewable'=>'0']);denied(fn()=>act($a,'renew'));$s=view($a,$oa);yes($s['state']==='ACTIVE'&&$s['assignment']['version']===$prior['version']);});
test('B trial and C scheduled initial subscription retain independent native scopes',function()use($b,$c,$ob,$oc,$t){act($b,'start-trial',['choice'=>'growth:1']);act($c,'start',['choice'=>'starter:1','effective'=>gmdate('Y-m-d\TH:i',$t+3600)]);yes(view($b,$ob)['state']==='TRIAL');yes(view($c,$oc)['state']==='SCHEDULED');denied(fn()=>(new Entitlements($GLOBALS['db'],$oc))->requireFeature($c['merchant'],$c['outlet'],'menu'));denied(fn()=>(new Entitlements($GLOBALS['db'],$oc))->overview($b['merchant'],$b['outlet']));});
test('Exact trial active grace and expiration UTC boundaries are derived without GET audit writes',function()use($b,$ob,&$t,$base,$db){$s=view($b,$ob);$n=(int)$db->query('SELECT COUNT(*) FROM merchant_subscription_events')->fetchColumn();$t=$s['lifecycle']['config']['trial_end']-1;yes(view($b,$ob)['state']==='TRIAL');$t++;yes(view($b,$ob)['state']==='ACTIVE');$t=(int)$s['assignment']['expires_epoch'];yes(view($b,$ob)['state']==='GRACE');(new Entitlements($db,$ob,static fn()=>$GLOBALS['t']))->requireFeature($b['merchant'],$b['outlet'],'menu');$t+=2*86400;yes(view($b,$ob)['state']==='EXPIRED');denied(fn()=>(new Entitlements($db,$ob,static fn()=>$GLOBALS['t']))->requireFeature($b['merchant'],$b['outlet'],'menu'));yes($n===(int)$db->query('SELECT COUNT(*) FROM merchant_subscription_events')->fetchColumn());$t=$base;});
test('Scheduled activation exact boundary and early activation use server time',function()use($c,$oc,&$t,$base){$s=view($c,$oc);$t=(int)$s['assignment']['effective_epoch']-1;yes(view($c,$oc)['state']==='SCHEDULED');$t++;yes(view($c,$oc)['state']==='ACTIVE');$t=$base;act($c,'activate',['choice'=>'starter:1']);yes(view($c,$oc)['state']==='ACTIVE');});
test('Invalid transition dates trial duration and grace bounds reject with no audit success',function()use($a,$c,$db){$n=(int)$db->query('SELECT COUNT(*) FROM merchant_subscription_events')->fetchColumn();denied(fn()=>act($a,'start-trial'));denied(fn()=>act($c,'activate'));denied(fn()=>act($c,'schedule',['choice'=>'starter:1','effective'=>'2026-02-30T12:00']));denied(fn()=>act($c,'renew',['choice'=>'starter:1','expires'=>'2000-01-01T00:00']));yes((int)$db->query('SELECT COUNT(*) FROM merchant_subscription_events')->fetchColumn()===$n);});
test('Trial activation and renewal extend pinned version without financial effects',function()use($b,$ob,$base){act($b,'activate',['choice'=>'growth:1']);yes(view($b,$ob)['state']==='ACTIVE');act($b,'renew',['choice'=>'growth:1','expires'=>gmdate('Y-m-d\TH:i',$base+60*86400)]);yes((int)view($b,$ob)['assignment']['expires_epoch']===$base+60*86400);});
test('Suspension denies new restaurant work yet existing A operational completion remains admitted',function()use($a,$oa,$db){act($a,'suspend');yes(view($a,$oa)['state']==='SUSPENDED');$x=new Entitlements($db,$oa,static fn()=>$GLOBALS['t']);denied(fn()=>$x->requireFeature($a['merchant'],$a['outlet'],'pos'));$x->requireFeature($a['merchant'],$a['outlet'],'kitchen','drain');$x->requireFeature($a['merchant'],$a['outlet'],'floor','drain-read');denied(fn()=>$x->requireFeature($a['merchant'],$a['outlet'],'billing'));denied(fn()=>(new StaffPos($db,$oa))->save($a['merchant'],$a['outlet'],kid(),'','0','',[]));});
test('Reactivation rejects unsafe removal during active operations and restores scoped full access',function()use($a,$oa){denied(fn()=>act($a,'reactivate',['choice'=>'starter:1']));act($a,'reactivate');yes(view($a,$oa)['state']==='ACTIVE');});
test('Legacy assignment path cannot bypass a lifecycle suspension',function()use($a,$oa,$e,$base){act($a,'suspend');[$v,$h]=versions($a);denied(fn()=>$e->assign(kid(),$a['merchant'],$h,'enterprise','3',gmdate('Y-m-d\TH:i',$base),gmdate('Y-m-d\TH:i',$base+86400),'Bypass attempt'));yes(view($a,$oa)['state']==='SUSPENDED');act($a,'reactivate');});
test('Period end cancellation overrides grace and authorized reactivation clears cancellation',function()use($c,$oc,&$t,$base){act($c,'cancel-end',['choice'=>'starter:1']);$s=view($c,$oc);$t=(int)$s['assignment']['expires_epoch']-1;yes(view($c,$oc)['state']==='ACTIVE');$t++;yes(view($c,$oc)['state']==='CANCELLED');$t=$base;denied(fn()=>act($c,'renew',['choice'=>'starter:1']));act($c,'reactivate',['choice'=>'starter:1']);yes(view($c,$oc)['lifecycle']['config']['cancel_at']===null);});
test('Immediate cancellation retains history and rejects repeated action without request replay',function()use($c,$oc){act($c,'cancel-now',['choice'=>'starter:1']);yes(view($c,$oc)['state']==='CANCELLED');denied(fn()=>act($c,'suspend'));denied(fn()=>act($c,'cancel-now'));act($c,'reactivate',['choice'=>'starter:1']);});
test('Scheduled upgrade takes effect exactly and discarded schedule cannot revive later',function()use($c,$oc,&$t,$base){act($c,'schedule',['choice'=>'growth:1','effective'=>gmdate('Y-m-d\TH:i',$base+120)]);yes(view($c,$oc)['assignment']['plan_id']==='starter');$t=$base+120;yes(view($c,$oc)['assignment']['plan_id']==='growth');$t=$base;act($c,'discard-schedule',['choice'=>'starter:1']);$t=$base+180;yes(view($c,$oc)['assignment']['plan_id']==='starter');$t=$base;});
test('Downgrade is rechecked at scheduled activation if new operational work arrived',function()use($b,$ob,&$t,$base,$db,&$testTable){act($b,'schedule',['choice'=>'starter:1','effective'=>gmdate('Y-m-d\TH:i',$base+180)]);$seat=new Seating($db,$ob);$f=$seat->act($b['merchant'],$b['outlet'],kid(),'floor',['id'=>'','version'=>'0','name'=>'Synthetic M06B floor','active'=>'1'])['result']['floor'];$testTable=$seat->act($b['merchant'],$b['outlet'],kid(),'table',['id'=>'','version'=>'0','floor'=>$f['floor_id'],'name'=>'Synthetic M06B hold','capacity'=>'2','type'=>'standard','active'=>'1','notes'=>'Lifecycle activation fixture'])['result']['table'];$seat->act($b['merchant'],$b['outlet'],kid(),'status',['table'=>$testTable['table_id'],'version'=>'1','state'=>'OCCUPIED','minutes'=>'30','party'=>'1','reason'=>'Synthetic activation interlock']);$t=$base+180;$s=view($b,$ob);yes($s['assignment']['plan_id']==='growth'&&$s['lifecycle']['change_blocked']);$t=$base;$seat->act($b['merchant'],$b['outlet'],kid(),'status',['table'=>$testTable['table_id'],'version'=>'2','state'=>'AVAILABLE','minutes'=>'1','party'=>'1','reason'=>'Explicit fixture completion']);$t=$base+180;yes(view($b,$ob)['assignment']['plan_id']==='starter');$t=$base;act($b,'discard-schedule',['choice'=>'growth:1']);});
test('Concurrent duplicate suspension commits one event and stale revisions cannot change state',function()use($c,$e,$argv,&$r){[$v,$h]=versions($c);$key=kid();$children=[];for($i=0;$i<2;$i++){$pipes=[];$p=proc_open([PHP_BINARY,__FILE__,$argv[1],$argv[2],$argv[3],'worker',$key,$c['merchant'],$v,$h],[0=>['pipe','r'],1=>['pipe','w'],2=>['pipe','w']],$pipes);yes(is_resource($p));fclose($pipes[0]);$children[]=[$p,$pipes];}$versions=[];foreach($children as[$p,$pipes]){$out=stream_get_contents($pipes[1]);$err=stream_get_contents($pipes[2]);fclose($pipes[1]);fclose($pipes[2]);$exit=proc_close($p);$r['workers'][]=['exit'=>$exit,'stderr'=>$err,'result'=>$out];yes($exit===0);$versions[]=json_decode($out,true)['version'];}yes($versions[0]===$versions[1]&&$versions[0]===(int)$v+1);denied(fn()=>$e->lifecycle(kid(),$c['merchant'],$v,$h,'reactivate',fields(['choice'=>'starter:1'])));denied(fn()=>$e->lifecycle($key,$c['merchant'],$v,$h,'cancel-now',fields()));act($c,'reactivate',['choice'=>'starter:1']);});
test('Audit write failure rolls back both new assignment and lifecycle revision',function()use($c,$db,$oc){[$v,$h]=versions($c);$count=(int)$db->query('SELECT COUNT(*) FROM merchant_plan_assignments')->fetchColumn();$db->exec("CREATE TRIGGER lifecycle_failure BEFORE INSERT ON merchant_subscription_events FOR EACH ROW SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='Synthetic audit failure'");try{denied(fn()=>act($c,'renew',['choice'=>'starter:1','expires'=>gmdate('Y-m-d\TH:i',$GLOBALS['base']+80*86400)]));yes(versions($c)===[$v,$h]);yes((int)$db->query('SELECT COUNT(*) FROM merchant_plan_assignments')->fetchColumn()===$count);}finally{$db->exec('DROP TRIGGER lifecycle_failure');}});
test('Cross merchant and foreign outlet operations remain denied under active entitlement',function()use($db,$oa,$a,$b,$c){denied(fn()=>(new Entitlements($db,$oa))->overview($c['merchant'],$c['outlet']));denied(fn()=>(new Entitlements($db,$oa))->requireFeature($a['merchant'],$b['outlet'],'menu'));$s=versions($c);denied(fn()=>(new Entitlements($db,$oa))->lifecycle(kid(),$c['merchant'],$s[0],$s[1],'suspend',fields()));});
test('Immutable lifecycle history cannot be updated or removed and source period records remain',function()use($db,$before){denied(fn()=>$db->exec("UPDATE merchant_subscription_events SET reason='Overwrite'"));denied(fn()=>$db->exec('DELETE FROM merchant_subscription_events'));yes(fingerprint()===$before);yes((int)$db->query('SELECT COUNT(*) FROM payment_confirmations')->fetchColumn()===0);yes(qualifiedMigrationSequence($db));});
test('Final synthetic owners retain independent active assigned plans for browser qualification',function()use($a,$b,$c,$oa,$ob,$oc){foreach([[$a,$oa,'enterprise'],[$b,$ob,'growth'],[$c,$oc,'starter']]as[$m,$auth,$plan]){yes(view($m,$auth)['state']==='ACTIVE');yes(view($m,$auth)['assignment']['plan_id']===$plan);}});
